    return result

def laplacian_matrix(G):
    n = len(G)
    L = [[0] * n for _ in range(n)]
    degree_sum = sum(sum(row) for row in G)
    for i in range(n):
        L[i][i] = degree_sum - 2 * sum(G[i])
        for j in range(i+1, n):
            if G[i][j]:
                L[i][j] = L[j][i] = -G[i][j]
    return L

def eigenvalue_lower_bound(L):
